use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(mut arr) = input {
        let mut non_zeros = arr.drain(..).filter(|v| !v.is_null() && *v.as_i64().unwrap() != 0).collect::<Vec<Value>>();
        let zeros = vec![Value::Null; arr.len()];
        non_zeros.extend(zeros);
        Value::Array(non_zeros)
    } else {
        input
    }
}
